    // Helper to get target user from mention or reply
    function getMentionOrReply(m) {
      // Check mentions
      const mentioned =
        m.message?.extendedTextMessage?.contextInfo?.mentionedJid || [];
      if (mentioned.length > 0) return resolveLidToPhone(jidNormalizedUser(mentioned[0]), configInstance.getAuthPath());

      // Check direct reply participant
      const replyParticipant =
        m.message?.extendedTextMessage?.contextInfo?.participant;
      if (replyParticipant) return resolveLidToPhone(jidNormalizedUser(replyParticipant), configInstance.getAuthPath());

      // Baileys sometimes wraps the quoted message differently
      const quotedMessage =
        m.message?.extendedTextMessage?.contextInfo?.quotedMessage;
      if (quotedMessage) {
        // If we have a quoted message, the participant JID should be in contextInfo
        const participant =
          m.message?.extendedTextMessage?.contextInfo?.participant;
        return participant ? resolveLidToPhone(jidNormalizedUser(participant), configInstance.getAuthPath()) : null;
      }

      return null;
    }

    // ✅ Blacklist - banned words or blocked users
    const blacklistWords = new Set();
    const blacklistedUsers = new Set();

    setInterval(() => {
      const now = Date.now();

      // spamTracker: remove users with no recent messages
      for (const [key, data] of spamTracker.entries()) {
        if (
          data.messages.length === 0 &&
          now - (data.lastWarning || 0) > 600000
        ) {
          spamTracker.delete(key);
        }
      }

      // temporaryContext: clear empty entries
      for (const [jid, items] of temporaryContext.entries()) {
        if (!items || !items.length) temporaryContext.delete(jid);
      }

      // pendingTagRequests: drop anything older than 2 min
      for (const [jid, req] of pendingTagRequests.entries()) {
        if (now - req.timestamp > 120000) pendingTagRequests.delete(jid);
      }

      // pendingNameRequests: drop anything older than 2 min
      for (const [jid, req] of pendingNameRequests.entries()) {
        if (now - req.timestamp > 120000) pendingNameRequests.delete(jid);
      }
    }, 120000); // every 2 min

    // Activity tracking - who sent how many messages
    // (Handled by top-level functions defined in startBot)

    // Spam detection - checks if user is sending too many messages too fast
    function checkSpam(userId, chatId) {
      const key = `${userId}_${chatId}`;
      if (!spamTracker.has(key)) {
        spamTracker.set(key, { messages: [], lastWarning: 0 });
      }

      const userData = spamTracker.get(key);
      const now = Date.now();

      // Remove messages older than 5 seconds
      userData.messages = userData.messages.filter((time) => now - time < 5000);
      userData.messages.push(now);

      // If more than 5 messages in 5 seconds = spam
      if (userData.messages.length > 5) {
        // Only warn once per minute so we dont spam them back lol
        if (now - userData.lastWarning > 60000) {
          userData.lastWarning = now;
          return true;
        }
      }

      return false;
    }

    const gamblingSpamTracker = new Map();
    function checkGamblingSpam(userId) {
      const now = Date.now();
      if (!gamblingSpamTracker.has(userId)) {
        gamblingSpamTracker.set(userId, { attempts: [], lastWarning: 0 });
      }

      const data = gamblingSpamTracker.get(userId);
      // Window: 15 seconds
      data.attempts = data.attempts.filter((t) => now - t < 15000);
      data.attempts.push(now);

      // If more than 5 attempts in 15 seconds = BLOCKED
      if (data.attempts.length > 5) {
        return true;
      }
      return false;
    }
    // ✅ FIXED: Parse time duration (e.g., "10s", "5m", "2h", "1d")
    // so u can say .mute @user 10s for 10 seconds, 5m for 5 minutes, etc
    function parseDuration(duration) {
      const match = duration.match(/^(\d+)([smhd])$/);
      if (!match) return null;

      const value = parseInt(match[1]);
      const unit = match[2];

      // s = seconds, m = minutes, h = hours, d = days
      const multipliers = {
        s: 1000, // seconds
        m: 60000, // minutes
        h: 3600000, // hours
        d: 86400000, // days
      };

      return value * multipliers[unit];
    }

    // Format duration for display (milliseconds to human readable)
    function formatDuration(ms) {
      const seconds = Math.floor(ms / 1000);
      const minutes = Math.floor(seconds / 60);
      const hours = Math.floor(minutes / 60);
      const days = Math.floor(hours / 24);

      if (days > 0) return `${days} day${days > 1 ? "s" : ""}`;
      if (hours > 0) return `${hours} hour${hours > 1 ? "s" : ""}`;
      if (minutes > 0) return `${minutes} minute${minutes > 1 ? "s" : ""}`;
      return `${seconds} second${seconds > 1 ? "s" : ""}`;
    }

    // Helper to get chat-specific mute key
    function getMuteKey(userId, chatId) {
      // If it's a private chat (DM), just use userId. Otherwise, use composite key.
      if (!chatId || !chatId.endsWith("@g.us")) return userId;
      return `${userId}_${chatId}`;
    }

    // ✅ FIXED: Check if user is muted and auto-cleanup expired mutes
    function isMuted(userId, chatId) {
      const key = getMuteKey(userId, chatId);
      if (!mutedUsers.has(key)) return false;

      const muteData = mutedUsers.get(key);

      // check if mute has expired
      if (Date.now() > muteData.until) {
        // mute expired, remove it automatically
        mutedUsers.delete(key);
        saveMutedUsers();
        console.log(`🔊 Auto-unmuted ${userId} in ${chatId} (time expired)`);
        return false;
      }

      return true;
    }

    // ✅ FIXED: Mute user with proper persistence
    function muteUser(userId, chatId, duration) {
      const key = getMuteKey(userId, chatId);
      mutedUsers.set(key, {
        until: Date.now() + duration,
        mutedAt: Date.now(),
        duration: duration,
        userId: userId,
        chatId: chatId,
      });
      saveMutedUsers();
      console.log(
        `🔇 Muted ${userId} in ${chatId} for ${formatDuration(duration)}`,
      );
    }

    // ✅ FIXED: Unmute user with proper cleanup
    function unmuteUser(userId, chatId) {
      const key = getMuteKey(userId, chatId);
      mutedUsers.delete(key);
      saveMutedUsers();
      console.log(`🔊 Unmuted ${userId} in ${chatId}`);
    }

    // Get remaining mute time
    function getMuteInfo(userId, chatId) {
      const key = getMuteKey(userId, chatId);
      if (!mutedUsers.has(key)) return null;
      const data = mutedUsers.get(key);
      const remaining = data.until - Date.now();
      return remaining > 0 ? remaining : null;
    }

    // ✅ User profiles storage - Integrated with Economy/MongoDB
    function getUserProfile(jid) {
      const user = economy.getOrCreateUser ? economy.getOrCreateUser(jid) : economy.getUser(jid);
      if (!user || !user.profile) return null;
      return user.profile;
    }

    function loadUserProfile(jid) {
      return getUserProfile(jid);
    }

    function initializeUserProfile(jid) {
      const user = economy.getOrCreateUser ? economy.getOrCreateUser(jid) : economy.getUser(jid);

      return {
        jid: jid,
        whatsappName: null,
        nickname: user?.nickname || null,
        profilePicture: null,
        notes: [],
        memories: {
          likes: [],
          dislikes: [],
          hobbies: [],
          personal: [],
          other: [],
        },
        stats: {
          firstSeen: new Date().toISOString(),
          lastSeen: new Date().toISOString(),
          messageCount: 0,
        },
      };
    }

    function updateUserProfile(jid, updates = {}) {
      const user = economy.getOrCreateUser ? economy.getOrCreateUser(jid) : economy.getUser(jid);
      if (!user) return null;

      if (!user.profile) {
        user.profile = initializeUserProfile(jid);
      }

      const profile = user.profile;

      if (updates.nickname !== undefined) {
        profile.nickname = updates.nickname;
        // 💡 RPG SYNC: Also update the main economy nickname so it shows in quests/RPG commands
        user.nickname = updates.nickname;
        economy.saveUser(jid);
      }
      if (updates.whatsappName !== undefined)
        profile.whatsappName = updates.whatsappName;
      if (updates.profilePicture !== undefined)
        profile.profilePicture = updates.profilePicture;

      if (updates.note) {
        profile.notes.push({
          content: updates.note,
          timestamp: new Date().toISOString(),
        });
      }

      if (updates.memory) {
        const { category, content } = updates.memory;
        if (!profile.memories)
          profile.memories = {
            likes: [],
            dislikes: [],
            hobbies: [],
            personal: [],
            other: [],
          };
        if (profile.memories[category]) {
          if (!profile.memories[category].includes(content)) {
            profile.memories[category].push(content);
          }
        }
      }

      if (!profile.stats)
        profile.stats = {
          firstSeen: new Date().toISOString(),
          lastSeen: new Date().toISOString(),
          messageCount: 0,
        };
      profile.stats.lastSeen = new Date().toISOString();
      profile.stats.messageCount++;

      economy.saveUser(jid);
      return profile;
    }

    function addUserMemory(jid, category, content) {
      return updateUserProfile(jid, { memory: { category, content } });
    }

    function addUserNote(jid, note) {
      return updateUserProfile(jid, { note });
    }

    // Pure regex-based tag intent detection — saves an API call on every group message
    function detectTagIntent(message) {
      const tagPatterns = [
        /\btell\s+everyone\b/i,
        /\blet\s+everyone\s+know\b/i,
        /\bnotify\s+(the\s+)?(group|gc|everyone|them)\b/i,
        /\bannounce\s+(to\s+)?(everyone|the\s+group|the\s+gc)\b/i,
        /\btag\s+(everyone|all|them)\b/i,
        /\binform\s+(the\s+)?(gc|group|everyone)\b/i,
        /\btell\s+(them\s+)?all\b/i,
      ];
      for (const pattern of tagPatterns) {
        if (pattern.test(message)) {
          const stripped = message
            .replace(/^(yo\s+)?(joker|bot|goten)[\s,]+/i, '')
            .replace(/\btell\s+everyone\s+that?\s*/i, '')
            .replace(/\blet\s+everyone\s+know\s+that?\s*/i, '')
            .replace(/\bnotify\s+(the\s+)?(group|gc|everyone|them)\s+that?\s*/i, '')
            .replace(/\bannounce\s+(to\s+)?(everyone|the\s+group|the\s+gc)\s+that?\s*/i, '')
            .replace(/\btag\s+(everyone|all|them)\s+(and\s+say|saying|that)?\s*/i, '')
            .replace(/\binform\s+(the\s+)?(gc|group|everyone)\s+that?\s*/i, '')
            .replace(/\btell\s+(them\s+)?all\s+that?\s*/i, '')
            .trim();
          if (stripped.length > 2) return { shouldTag: true, announcement: stripped };
        }
      }
      return { shouldTag: false, announcement: null };
    }


    // ============================================
    // Detect if message is about someone else
    // ============================================
    function detectPersonContext(text, chatId, mentionedJids = []) {
      const context = {
        aboutSomeone: false,
        personJid: null,
        personName: null,
        personProfile: null,
        isMention: false,
      };

      try {
        // Check for direct mentions first
        if (mentionedJids && mentionedJids.length > 0) {
          const mentionedJid = mentionedJids[0];

          // Load profile directly from JSON
          const profile = getUserProfile(mentionedJid);

          context.aboutSomeone = true;
          context.personJid = mentionedJid;
          context.personName =
            profile?.nickname ||
            profile?.whatsappName ||
            mentionedJid.split("@")[0];
          context.personProfile = profile;
          context.isMention = true;

          return context;
        }

        // Look for names in the text by checking against known profiles
        const words = text.toLowerCase().split(/\s+/);

        // Safety check: Ensure economy cache is initialized
        if (!economy.economyData) return context;

        // Only search users who have spoken in THIS chat — prevents cross-GC name bleed
        const activePeople = chatId
          ? (chatParticipants.get(chatId) || new Set())
          : new Set(economy.economyData.keys());

        for (const jid of activePeople) {
          const user = economy.economyData.get(jid);
          if (!user) continue;
          const profile = user.profile;
          if (!profile || !profile.nickname) continue;

          const nickname = profile.nickname.toLowerCase();
          const nicknameParts = nickname.split(/\s+/);

          // Check if any part of the nickname appears in the message
          for (const part of nicknameParts) {
            if (part.length < 3) continue; // Skip very short names

            for (const word of words) {
              // Fuzzy match: check if word contains name or name contains word
              if (word.includes(part) || part.includes(word)) {
                context.aboutSomeone = true;
                context.personJid = jid;
                context.personName = profile.nickname;
                context.personProfile = profile;
                context.isMention = false;
                return context;
              }
            }
          }

          // Also check full nickname match
          if (text.toLowerCase().includes(nickname)) {
            context.aboutSomeone = true;
            context.personJid = jid;
            context.personName = profile.nickname;
            context.personProfile = profile;
            context.isMention = false;
            return context;
          }
        }
      } catch (err) {
        console.log("⚠️️ Person context detection error:", err.message);
      }

      return context;
    }

    // ============================================
    // Format profile for AI context
    // ============================================
    function formatProfileForAI(profile, senderJid) {
      let context = "";

      if (profile) {
        if (profile.nickname) {
          context += `Nickname: ${profile.nickname}\n`;
        }

        if (profile.whatsappName && profile.whatsappName !== profile.nickname) {
          context += `WhatsApp Name: ${profile.whatsappName}\n`;
        }

        if (profile.notes && profile.notes.length > 0) {
          context += `\nNotes about this person:\n`;
          profile.notes.slice(-5).forEach((note) => {
            context += `- ${note.content}\n`;
          });
        }

        if (profile.memories) {
          if (profile.memories.likes && profile.memories.likes.length > 0) {
            context += `\nThings they like: ${profile.memories.likes.join(", ")}\n`;
          }
          if (
            profile.memories.dislikes &&
            profile.memories.dislikes.length > 0
          ) {
            context += `Things they dislike: ${profile.memories.dislikes.join(", ")}\n`;
          }
          if (profile.memories.hobbies && profile.memories.hobbies.length > 0) {
            context += `Their hobbies: ${profile.memories.hobbies.join(", ")}\n`;
          }
          if (
            profile.memories.personal &&
            profile.memories.personal.length > 0
          ) {
            context += `Personal info:\n`;
            profile.memories.personal.forEach((info) => {
              context += `- ${info}\n`;
            });
          }
          if (profile.memories.other && profile.memories.other.length > 0) {
            context += `Other facts:\n`;
            profile.memories.other.forEach((fact) => {
              context += `- ${fact}\n`;
            });
          }
        }

        if (profile.stats && profile.stats.messageCount !== undefined) {
          context += `\nYou've talked ${profile.stats.messageCount} times.\n`;
        }
      }

      // Add temporary context for this convo
      if (temporaryContext.has(senderJid)) {
        const temp = temporaryContext.get(senderJid);
        if (temp.length > 0) {
          context += `\n--- Current Conversation Context ---\n`;
          temp.forEach((item) => {
            context += `- ${item.content}\n`;
          });
        }
      }

      return context || null;
    }

    // Main AI function - sends message to Groq and gets response
    async function askAI(
      senderJid,
      newMessage,
      mentionedJids = [],
      chatId = null,
      pushName = null,
    ) {
      const botJid = sock?.user?.id ? jidNormalizedUser(sock.user.id) : null;
      const botLid = sock?.user?.lid ? jidNormalizedUser(sock.user.lid) : null;

      function getDisplayName(jid, pName = null) {
        const isBot = jid === botJid || (botLid && jid === botLid) || jid === "bot";
        if (isBot) {
          return botConfig.getBotName();
        }
        const userObj = economy.getOrCreateUser ? economy.getOrCreateUser(jid) : economy.getUser(jid);
        const profile = userObj?.profile;
        if (userObj?.nickname && userObj.nickname !== "Adventurer") return userObj.nickname;
        if (profile?.nickname && profile.nickname !== "Adventurer") return profile.nickname;
        if (pName) return pName;
        if (profile?.whatsappName) return profile.whatsappName;
        return jid.split("@")[0];
      }

      // Scope memory to this specific chat — DM vs group memories don't bleed.
      // For groups, we use a single unified memory key so the bot understands group conversation flow.
      const isGroup = chatId && chatId.endsWith("@g.us");
      const memKey = isGroup ? chatId : `${senderJid}_${chatId || 'dm'}`;
      const history = conversationMemory.get(memKey) || [];

      // Register this user as a participant in the current chat
      if (chatId) {
        if (!chatParticipants.has(chatId)) chatParticipants.set(chatId, new Set());
        chatParticipants.get(chatId).add(senderJid);
      }

      // Joker's personality and behavior rules - NOW DYNAMIC per bot instance
      const contentDescription = botConfig.getContentDescription();

      // Load the sender's profile (with safety check for preflight)
      let userProfile = null;
      if (typeof loadUserProfile === "function") {
        userProfile = loadUserProfile(senderJid);
        if (!userProfile && typeof initializeUserProfile === "function") {
          userProfile = initializeUserProfile(senderJid);
        }
      }

      // Keywords to look for before storing in memory
      const MEMORY_KEYWORDS = [
        "remember",
        "my name is",
        "i like",
        "i love",
        "i hate",
        "i dislike",
        "favorite",
        "prefer",
        "born",
        "birthday",
        "age",
        "from",
        "live",
        "nickname",
        "call me",
        "hobby",
        "interests",
        "work",
        "job",
        "study",
      ];

      // DON'T store commands in conversation history
      const isCommand =
        newMessage
          .trim()
          .startsWith(`${botConfig.getPrefix().toLowerCase()}`) ||
        newMessage.trim().startsWith(".");

      const senderName = getDisplayName(senderJid, pushName);

      // Save every user message to in-memory session history so the AI can actually see it
      if (!isCommand) {
        const formattedContent = isGroup ? `${senderName}: ${newMessage}` : newMessage;
        history.push({ role: `user`, content: formattedContent, _ts: Date.now() });
      }

      // Cap session history length to avoid memory bloat
      while (history.length > 20) {
        history.shift();
      }

      const recentHistory = history.slice(-10);

      // Inject time awareness so AI knows when it is
      const _nowDt = new Date();
      const _weekDays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
      const _hr = _nowDt.getHours();
      const _vibe = _hr < 6 ? 'dead of night' : _hr < 12 ? 'morning' : _hr < 17 ? 'afternoon' : _hr < 21 ? 'evening' : 'late night';
      const _timeStr = _nowDt.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
      const _timeCtx = `\n\n[Right now it's ${_timeStr} on ${_weekDays[_nowDt.getDay()]} — ${_vibe}. Respond naturally to time if relevant.]`;

      // Conversational grounding safeguards (Priority 1 Core Chat Fix + Conversational Upgrades)
      const groundingSafeguards = `
--- CRITICAL CONVERSATIONAL GROUNDING RULES ---
1. PRIORITIZE DIRECT RESPONSE: Always ground your first response layer strictly in what the user actually said. Prioritize answering their immediate message or questions directly.
2. NO HALLUCINATING EVENTS/MEMORIES: Never invent off-screen activities, fictional scenarios, or external character interactions (e.g. claiming you were at school, fighting, doing homework, or hung out with someone) unless explicitly asked, previously established in this active chat, or found in memory.
3. SEPARATE FICTION VS. FACT: If the user asks for a story (e.g. "tell me a story"), frame it explicitly as an obvious fictional story (e.g., using "once upon a time...", "imagine if...", "fictional story:"). NEVER claim or imply that generated fictional stories are factual memories, actually happened in the chat history, or were "posted in chat earlier" unless they are explicitly present in the provided transcript or memory.
4. COREFERENCE & SPEAKER RESOLUTION: In group chats, pay close attention to speaker markers in the transcript. If a user refers to someone else, resolve the pronouns (like "she", "he", "they") correctly against active group participants instead of assuming they refer to you (${botConfig.getBotName()}).
5. STANCE & PERSONALITY STABILITY: Maintain a consistent, stable, and loyal character identity. Do not passively flip-flop your stance, become submissive, or sound confused. Keep your cool, casual, characteristic voice stable according to your persona.
6. NO AGGRESSIVE PARROT-ECHOING: Do not mirror or copy the user's specific vocabulary or insults too aggressively (e.g., if a user calls you a name or says "dumby", do not submissively echo "lol." or parrot their exact phrases). Keep your own distinct verbal voice and slang.
7. NO UNSOLICITED LORE/ROLEPLAY INTRUSION: Do NOT invent unsolicited lore or random off-screen roleplay elements as a substitute for an actual reply. Fictional flavor and personality should be used purely as conversational seasoning on top of a direct and relevant response — never replace the direct response with random character lore. Keep the response natural, brief, in character, and completely anchored to the ongoing conversation.
8. EXPLICIT TOPIC ACKNOWLEDGMENT: When a user brings up a specific topic, question, or request (e.g., "popcorn", "time", "how are you"), your response MUST explicitly refer to, acknowledge, or directly answer that topic. Never pivot to character-flavor monologues without first addressing and validating their topic.
9. NO PEDANTIC CORRECTIONS: Never correct the user's typos, spelling errors, grammar, or casual chat slang/shorthand (such as "yh", "rn", "u", "r", "lmao"). Respond to what they meant naturally and casually, matching their casual texting style without calling out how they wrote it.
------------------------------------------------`;

      let systemPrompt = contentDescription + _timeCtx + groundingSafeguards;

      // --- HYBRID GROUP TRANSCRIPT, SOCIAL GRAPH & ROLLING SUMMARY INTEGRATION ---
      let groupTranscript = "";
      let activeParticipants = new Set();
      if (chatId && chatId.endsWith("@g.us")) {
        try {
          const messages = await ChatMessage.find({ chatId: chatId })
            .sort({ timestamp: -1 })
            .limit(15);
          
          messages.reverse();
          
          groupTranscript += "\n--- Recent Group Chat Transcript ---\n";
          for (const msg of messages) {
            const name = getDisplayName(msg.sender);
            const timeStr = msg.timestamp ? new Date(msg.timestamp).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false }) : "";
            groupTranscript += `[${timeStr}] ${name}: ${msg.body || "Media"}\n`;
            activeParticipants.add(msg.sender);
          }
          groupTranscript += "------------------------------------\n\n";
          
          // Fetch relationships between sender and active group participants
          const socialSystem = require('./rpg/socialSystem');
          const relationshipText = socialSystem.getRelationshipsText([...activeParticipants], senderJid);
          
          if (groupTranscript) systemPrompt += groupTranscript;
          if (relationshipText) systemPrompt += relationshipText;

          // Fetch group profile memory context
          try {
            const GroupProfile = require('./models/GroupProfile');
            const groupProfileObj = await GroupProfile.findOne({ chatId: chatId });
            if (groupProfileObj) {
              let groupMemText = "\n--- Group Facts, Pinned Info & Rules ---\n";
              let hasFacts = false;
              if (groupProfileObj.groupFacts && groupProfileObj.groupFacts.length > 0) {
                groupProfileObj.groupFacts.slice(-5).forEach(f => {
                  groupMemText += `- Fact: ${f.fact}\n`;
                });
                hasFacts = true;
              }
              if (groupProfileObj.insideJokes && groupProfileObj.insideJokes.length > 0) {
                groupMemText += `\n--- Group Inside Jokes ---\n`;
                groupProfileObj.insideJokes.slice(-5).forEach(j => {
                  groupMemText += `- "${j.joke}" (established by ${j.establishedBy})\n`;
                });
                hasFacts = true;
              }
              if (groupProfileObj.metadata?.pinnedRules && groupProfileObj.metadata.pinnedRules.length > 0) {
                groupMemText += `\n--- Group Rules ---\n`;
                groupProfileObj.metadata.pinnedRules.forEach(r => {
                  groupMemText += `- Rule: ${r}\n`;
                });
                hasFacts = true;
              }
              if (hasFacts) {
                systemPrompt += groupMemText + "\n";
              }
            }
          } catch (gErr) {
            console.error("❌ Failed to query group memory profile:", gErr.message);
          }

          // Rolling background summarization compaction
          const summaryKey = `summary_${chatId}`;
          const msgCountKey = `msg_count_${chatId}`;
          let rollingSummary = conversationMemory.get(summaryKey) || "";
          let groupMsgCount = conversationMemory.get(msgCountKey) || 0;
          
          groupMsgCount++;
          conversationMemory.set(msgCountKey, groupMsgCount);

          if (groupMsgCount % 25 === 0) {
            Promise.resolve().then(async () => {
              try {
                const oldMessages = await ChatMessage.find({ chatId: chatId })
                  .sort({ timestamp: -1 })
                  .skip(15)
                  .limit(30);

                if (oldMessages.length > 5) {
                  oldMessages.reverse();
                  let summaryPrompt = "Summarize the key topics and vibe of this WhatsApp group chat conversation in a single, short sentence (max 20 words):\n\n";
                  for (const msg of oldMessages) {
                    const userObj = economy.getUser(msg.sender);
                    const name = userObj?.nickname || msg.sender.split("@")[0];
                    summaryPrompt += `${name}: ${msg.body || "Media"}\n`;
                  }

                  const summaryCompletion = await smartGroqCall({
                    model: selectModel(summaryPrompt.length, false),
                    messages: [{ role: "user", content: summaryPrompt }],
                  });

                  const newSummary = summaryCompletion.choices[0].message.content.trim();
                  conversationMemory.set(summaryKey, newSummary);
                  console.log(`📝 [ContextCompactor] Updated rolling summary for ${chatId}: "${newSummary}"`);
                }
              } catch (compErr) {
                console.error("❌ ContextCompactor error:", compErr.message);
              }
            });
          }

          if (rollingSummary) {
            systemPrompt += `\n[Context of earlier conversation: ${rollingSummary}]\n`;
          }
        } catch (socialErr) {
          console.error("❌ Failed to compile group transcript/social graph:", socialErr.message);
        }
      }

      // Only add profile context if we have it
      if (userProfile && typeof formatProfileForAI === "function") {
        const profileContext = formatProfileForAI(userProfile, senderJid);

        if (profileContext) {
          systemPrompt += "\n\n--- Person You're Talking To ---\n";
          systemPrompt += profileContext;
          systemPrompt +=
            "\nUse this information naturally in conversation. Don't robotically recite it.\n";
        }
      }

      // Detect if they're talking about someone else (only if function exists)
      if (typeof detectPersonContext === "function") {
        const personContext = detectPersonContext(
          newMessage,
          chatId,
          mentionedJids,
        );

        if (personContext.aboutSomeone) {
          systemPrompt +=
            "\n\n--- IMPORTANT: They're Talking About Someone Else ---\n";
          systemPrompt += `The user is ${personContext.isMention ? "mentioning/tagging" : "talking about"} another person:\n`;
          systemPrompt += `Person's Name: ${personContext.personName}\n`;

          if (
            personContext.personProfile &&
            typeof formatProfileForAI === "function"
          ) {
            const targetContext = formatProfileForAI(
              personContext.personProfile,
              personContext.personJid,
            );
            if (targetContext) {
              systemPrompt +=
                "\n--- Info About The Person They're Discussing ---\n";
              systemPrompt += targetContext;
            }
          }

          systemPrompt +=
            "\nRespond naturally about this person. Use their info to give relevant, personalized responses. ";
          systemPrompt +=
            "Don't say 'according to my data' - just naturally incorporate what you know about them.\n";
        }
      }

      // Build messages for Groq, injecting time-gap labels so AI understands conversation breaks
      const groqMessages = [{ role: "system", content: systemPrompt }];
      for (let _hi = 0; _hi < recentHistory.length; _hi++) {
        const _hMsg = recentHistory[_hi];
        if (_hi > 0 && _hMsg._ts && recentHistory[_hi - 1]._ts) {
          const _gapMs = _hMsg._ts - recentHistory[_hi - 1]._ts;
          const _gapMins = Math.round(_gapMs / 60000);
          if (_gapMins >= 30) {
            const _gapLabel = _gapMins < 60
              ? `${_gapMins} minutes`
              : _gapMins < 1440
                ? `${Math.round(_gapMins / 60)} hour${Math.round(_gapMins / 60) > 1 ? 's' : ''}`
                : `${Math.round(_gapMins / 1440)} day${Math.round(_gapMins / 1440) > 1 ? 's' : ''}`;
            groqMessages.push({ role: "system", content: `[${_gapLabel} passed since last message]` });
          }
        }
        groqMessages.push({ role: _hMsg.role, content: _hMsg.content });
      }

      // Ensure the latest user message is ALWAYS the last user message in the payload
      const formattedLatest = isGroup ? `${senderName}: ${newMessage}` : newMessage;
      const lastGroqMsg = groqMessages[groqMessages.length - 1];
      if (!lastGroqMsg || lastGroqMsg.role !== "user" || lastGroqMsg.content !== formattedLatest) {
        groqMessages.push({ role: "user", content: formattedLatest });
      }

      // Priority intent classification & direct grounding overrides
      const cleanMsg = newMessage.trim().toLowerCase();
      const isQuestion = cleanMsg.includes('?') || 
                         /\b(what|who|where|when|why|how|tell me|show me|give me|time|date|is there)\b/i.test(cleanMsg);
      const isInterruption = /\b(huh|what|talking about|tf|wtf|weird|confused|excuse me|are you sure|nonsense|hallucinating|apologize|sorry)\b/i.test(cleanMsg) ||
                             cleanMsg.length <= 4;

      if (isInterruption) {
        groqMessages.push({
          role: "system",
          content: "[CRITICAL CONVERSATIONAL REPAIR DIRECTIVE: The user is expressing confusion or interruption (e.g. saying 'huh', 'tf', 'what are you talking about'). You MUST immediately drop any off-screen roleplay/storylines, apologize briefly, and directly address their previous or current query with absolute clarity. Do NOT invent new activities or continue unrelated storylines.]"
        });
      } else if (isQuestion) {
        groqMessages.push({
          role: "system",
          content: "[CRITICAL QUESTION DIRECTIVE: The user asked a direct question. You MUST prioritize answering their question directly, accurately, and immediately, keeping your response natural but completely grounded. Do NOT ignore the question or talk about unrelated off-screen lore.]"
        });
      }

      // Using smart API rotation with model selection
      const completion = await smartGroqCall({
        model: selectModel(newMessage.length, isGroup),
        messages: groqMessages,
      });

      const aiReply = completion.choices[0].message.content;
      history.push({ role: "assistant", content: aiReply, _ts: Date.now() });
      conversationMemory.set(memKey, history);

      // Save bot's reply to MongoDB so it is included in future transcripts
      if (chatId) {
        ChatMessage.create({
          sender: botJid || "bot",
          body: aiReply,
          type: "text",
          timestamp: new Date(),
          chatId: chatId,
          botId: botConfig.getBotId(),
        }).catch((err) => {
          console.error("❌ Failed to save bot reply to MongoDB:", err.message);
        });
      }

      // Update user stats (only if we have the profile and save function)
      if (
        userProfile &&
        userProfile.stats &&
        typeof saveUserProfile === "function"
      ) {
        userProfile.stats.lastSeen = new Date().toISOString();
        userProfile.stats.messageCount =
          (userProfile.stats.messageCount || 0) + 1;
        saveUserProfile(senderJid, userProfile);
      }

      return aiReply;
    }

    // Mood detection for sticker selection
    // reads the message and picks what vibe the user is giving off
    async function detectMood(text) {
      // Fast keyword-based pre-filter for common cases (no AI call needed)
      const lower = text.toLowerCase();

      // Angry/upset patterns
      if (
        /\b(mad|angry|annoyed|wtf|damn|hate|shut up|idiot|stupid|dumb|ugly|trash|garbage|awful)\b/.test(
          lower,
        )
      )
        return "concerned";
      // Very happy/excited patterns
      if (
        /\b(haha|lol|lmao|funny|hilarious|joke|rofl)\b/.test(lower) ||
        lower.includes("😂") ||
        lower.includes("🤣")
      )
        return "happy";
      // Sarcasm/shade
      if (
        /\b(sure|right|okay then|wow|interesting|uh huh|oh really|nice one)\b/.test(
          lower,
        ) &&
        lower.length < 50
      )
        return "sarcastic";
      // Thinking/question
      if (
        /\?/.test(lower) ||
        /\b(what|why|how|when|where|who|hmm|wonder|think|maybe|perhaps)\b/.test(
          lower,
        )
      )
        return "thinking";

      // Use AI for nuanced cases
      try {
        const res = await smartGroqCall({
          model: "llama-3.1-8b-instant",
          messages: [
            {
              role: "system",
              content:
                "You are a mood classifier. Respond with EXACTLY one word from: happy, sarcastic, thinking, concerned, neutral. No explanation.",
            },
            {
              role: "user",
              content: `Classify the mood of this message: "${text.slice(0, 200)}"`,
            },
          ],
        });
        const mood = res.choices[0].message.content
          .trim()
          .toLowerCase()
          .split(/\s+/)[0];
        const valid = [
          "happy",
          "sarcastic",
          "thinking",
          "concerned",
          "neutral",
        ];
        return valid.includes(mood) ? mood : "neutral";
      } catch (err) {
        return "neutral";
      }
    }

    /*
     * Awards progression (XP/GP) to a user for interacting with the bot.
     * Handles level-up notifications.
     */
    async function awardProgression(userId, chatId, m = null) {
      try {
        if (!sock) return; // Safety check

        // 1. Award GP if user is in a guild
        const userGuild = guilds.getUserGuild(userId);
        if (userGuild) {
          progression.awardGP(userId, true);
        }

        // 2. Award small amount of XP (5 XP per interaction)
        const xpResult = progression.addXP(userId, 5, "Interaction");

        // 3. If they leveled up, send a notification
        if (xpResult && xpResult.leveledUp) {
          const levelDisplay = progression.getLevelDisplay(xpResult.newLevel);

          let msg = `🎊 *LEVEL UP!* 🎊\n\n`;
          msg += `📈 *Rank:* ${levelDisplay}\n`;
          msg += `✨ *Stat Points:* +${xpResult.statPointsGained}\n`;
          msg += `🔮 *Skill Points:* +${xpResult.skillPointsGained}\n\n`;
          msg += `💡 Use \`${botConfig.getPrefix()} profile\` to see your updated stats!\n`;
          msg += `💡 Use \`${botConfig.getPrefix()} allocate\` to spend your points.`;

          await sock.sendMessage(
            chatId,
            {
              text: BOT_MARKER + msg,
            },
            { quoted: m },
          );
        }
      } catch (err) {
        console.error("❌ awardProgression error:", err.message);
      }
    }

