                            `*Gists:* ${profile.public_gists}`,
                            `*Followers:* ${profile.followers} | *Following:* ${profile.following}`,
                            `*Company:* ${profile.company || "None"}`,
                            `*Location:* ${profile.location || "Earth"}`,
                            `*Profile Link:* ${profile.html_url}`,
                            `━━━━━━━━━━━━━━━━━`
